using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
internal static class WorkspaceUiTests {
 internal static void Run(){
  string root=Path.Combine(Path.GetTempPath(),"RemsupWorkspace-"+Guid.NewGuid().ToString("N"));string preference=Appearance.PreferencePath;bool dark=Appearance.Dark;
  try{Appearance.PreferencePath=Path.Combine(root,"appearance.txt");SettingsDraft();var store=new DeviceStore(Path.Combine(root,"devices-v2.json"));var data=store.Load();
   data.Upsert(new DeviceRecord{DisplayName="Demo workstation",DeviceId="123456789",UseDefaultRelay=true,IsFavorite=true,SavePermanentPassword=true,PermanentPassword="synthetic-a"});data.Upsert(new DeviceRecord{DisplayName="Demo laptop",DeviceId="987654321",Host="192.168.1.25",Transport=DeviceTransport.Lan,Pin=RelayTls.DefaultPin,Port=8444,SavePermanentPassword=true,PermanentPassword="synthetic-b"});store.Save(data);
   using(var form=NewForm(store)){
    Exception flowError=null;form.Shown+=async(sender,eventArgs)=>{try{var list=Field<ListView>(form,"devices");list.Items[1].Selected=true;Application.DoEvents();Check(Field<TextBox>(form,"quickId").Text=="987654321"&&Field<DeviceRecord>(form,"selectedContext").Transport==DeviceTransport.Lan,"select card keeps LAN credential/endpoint context");Field<TextBox>(form,"quickId").Text="111222333";Check(Field<DeviceRecord>(form,"selectedContext")==null&&list.SelectedItems.Count==0,"editing ID clears saved profile/credential context");var editedQuick=Field<DeviceRecord>(form,"quickProfile");Check(editedQuick.Transport==DeviceTransport.Lan&&editedQuick.Host=="192.168.1.25"&&!editedQuick.SavePermanentPassword&&editedQuick.PermanentPassword=="","editing ID preserves explicit LAN endpoint without silently selecting Default or reusing credential");
    Field<TextBox>(form,"search").Text="Demo laptop";Check(list.Items.Count==1,"card search");Field<TextBox>(form,"search").Clear();Field<ComboBox>(form,"filter").SelectedIndex=1;Check(list.Items.Count==1&&((DeviceRecord)list.Items[0].Tag).IsFavorite,"native card favorites");Field<ComboBox>(form,"filter").SelectedIndex=0;
    list.Items[0].Selected=true;Invoke(form,"Favorite");Check(!store.Load().Records[0].IsFavorite,"favorite persisted through real action");list.Items[0].Selected=true;Invoke(form,"Remove");Check(store.Load().Records.Count==1,"remove local profile persists without changing receiving host");
    var first=data.Records[0];var second=data.Records[1];await (Task)Invoke(form,"Connect",first);await (Task)Invoke(form,"Connect",second);Check(form.Workspace.Sessions.Count==2&&Field<TabControl>(form,"tabs").TabPages.Count==3,"two checked targets have native independent tabs");
    var one=form.Workspace.Sessions[0];var two=form.Workspace.Sessions[1];Check(one.Result.Stdout.Contains("123456789")&&two.Result.Stdout.Contains("987654321"),"actual per-tab results isolated");
    var tabs=Field<TabControl>(form,"tabs");var message=Message.Create(form.Handle,0,IntPtr.Zero,IntPtr.Zero);typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Tab});Check(tabs.SelectedIndex==0&&Field<RadioButton>(form,"homeNav").Checked,"Ctrl+Tab wraps from last session to Home library");typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Tab});Check(Field<RadioButton>(form,"settingsNav").Checked,"Ctrl+Tab includes Settings");typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Tab});Check(tabs.SelectedIndex==1&&Field<RadioButton>(form,"homeNav").Checked,"Ctrl+Tab traverses Settings to first device session");typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Shift|Keys.Tab});typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Shift|Keys.Tab});typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.Shift|Keys.Tab});Check(tabs.SelectedIndex==2,"reverse keyboard navigation restores checked tab");
    var nav=Field<RadioButton>(form,"settingsNav");form.SettingsEditor.relayHostBox.Text="draft.example.test";nav.PerformClick();form.SettingsEditor.SelectCategory(2);Field<RadioButton>(form,"homeNav").PerformClick();nav.PerformClick();Check(form.SettingsEditor.relayHostBox.Text=="draft.example.test"&&form.Workspace.Sessions.Count==2,"Home/Settings navigation preserves staged settings and tabs");
    Check(Find<RemsupSupportPanel>(form).Snapshot.State==SupportState.Stopped,"UI/navigation does not start synthetic receiving host");Check(!Controls(Find<RemsupSupportPanel>(form)).Any(c=>c is TextBox&&c.Parent!=null&&c.AccessibleName=="Observed receiving status history"),"no active sidebar log");
    Field<RadioButton>(form,"homeNav").PerformClick();Check(tabs.SelectedTab.Text=="Saved devices"&&form.Workspace.Sessions.Count==2,"Home returns to library without closing sessions");tabs.SelectedIndex=1;typeof(DesktopForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{message,Keys.Control|Keys.W});Check(!one.HasCredential&&one.History.Count==0&&form.Workspace.Sessions.Count==1,"Ctrl+W clears secret/history and preserves another tab");form.Close();Check(two.IsClosed&&!two.HasCredential,"app close clears every tab");}catch(Exception ex){flowError=ex;}finally{form.Close();}};Application.Run(form);if(flowError!=null)throw flowError;
   }
   var restored=store.Load();restored.Upsert(data.Records[0]);store.Save(restored);NativeCaptures(store);SessionStateUiTests.Run(store);Console.WriteLine("PASS workspace cards/context/CRUD/staged settings/native independent tabs/close");
  }finally{Appearance.PreferencePath=preference;Appearance.Dark=dark;if(Directory.Exists(root))Directory.Delete(root,true);}
 }
 static DesktopForm NewForm(DeviceStore store){return new DesktopForm(store,new RemsupSupportPanel(()=>new RemsupSettings{RelayHost=""},()=>new SupportStatus{DeviceId="111222333"}),()=>new RelayConfiguration("relay.example.test",8443,RelayTls.DefaultPin),false,(endpoint,device,password,command,seconds,bytes,cancel)=>new CommandResult{ExitCode=0,Stdout=device.DeviceId+"\r\nDEMO-PC\\demo\r\n"+command+"\r\n",DurationMs=42},_=>true);}
 static void SettingsDraft(){
  var current=new RemsupSettings{RelayHost="first.example.test",RelayPort=9443,PermanentPassword="synthetic-original"};int saved=0,changed=0;using(var container=new Form{Size=new Size(700,620)})using(var editor=new SettingsControl(()=>current,value=>{saved++;current=value;},_=>{})){
   container.Controls.Add(editor);container.Show();Application.DoEvents();Check(editor.saveStatus.Text.Contains("staged")&&!editor.saveStatus.Text.Contains("discarded"),"initial Settings status is neutral");editor.SettingsSaved+=()=>changed++;editor.relayHostBox.Text="draft.example.test";editor.SelectCategory(1);editor.CreateControl();var clear=Controls(editor).OfType<Button>().First(b=>b.Text=="Clear password");clear.PerformClick();Check(saved==0&&changed==0&&editor.permanentPasswordBox.Text==""&&current.PermanentPassword=="synthetic-original"&&editor.relayHostBox.Text=="draft.example.test","Clear stages password only without applying unrelated network draft");editor.Reload(true);Check(editor.permanentPasswordBox.Text=="synthetic-original"&&editor.relayHostBox.Text=="first.example.test"&&saved==0,"Discard restores password and unrelated draft without persistence");editor.SelectCategory(2);editor.relayHostBox.Text="draft.example.test";editor.SelectCategory(1);editor.SelectCategory(2);Check(saved==0&&changed==0&&editor.relayHostBox.Text=="draft.example.test","category navigation does not discard/persist/reconfigure draft");editor.Reload();Check(editor.relayHostBox.Text=="first.example.test"&&saved==0,"Discard restores saved fields without writing");
   editor.relayPortBox.Text="bad";editor.SelectCategory(0);Check(!editor.SaveDraft()&&saved==0&&changed==0,"Save from General validates invalid hidden Network draft");editor.relayPortBox.Text="10443";editor.permanentPasswordBox.Text="invalid space";Check(!editor.SaveDraft()&&saved==0,"hidden Security validates every Save");editor.permanentPasswordBox.Clear();editor.lanEnabled.Checked=true;editor.lanAddress.Text="8.8.8.8";Check(!editor.SaveDraft()&&saved==0,"invalid LAN rejected before settings persistence");editor.lanEnabled.Checked=false;editor.relayHostBox.Text="";editor.relayPortBox.Text="";Check(editor.SaveDraft()&&saved==1&&changed==1&&current.RelayHost==RelayConfiguration.DefaultHost&&current.RelayPort==443&&current.RelayPin==RelayTls.DefaultPin,"blank relay Save uses pinned owner TLS default");
  }
 }
 static void NativeCaptures(DeviceStore store){
  string evidence=Environment.GetEnvironmentVariable("REMSUP_WORKSPACE_UI_EVIDENCE")??Environment.GetEnvironmentVariable("REMSUP_LIVE_UI_EVIDENCE");if(string.IsNullOrEmpty(evidence)){Console.WriteLine("SKIP native workspace capture: evidence directory not set");return;}Directory.CreateDirectory(evidence);
  foreach(bool dark in new[]{false,true})using(var form=NewForm(store))using(var timer=new System.Windows.Forms.Timer{Interval=500}){
   Appearance.Dark=dark;Appearance.Apply(form);form.Location=new Point(8,8);form.StartPosition=FormStartPosition.Manual;form.TopMost=true;int step=0;Exception error=null;bool progressing=false;
   form.Shown+=(s,e)=>timer.Start();timer.Tick+=async(s,e)=>{if(progressing)return;progressing=true;try{
    string theme=dark?"dark":"light";string[] names={"home","home-compact","settings-network","settings-security","sessions-two","session-history","sessions-compact"};FriendlyUiTests.Capture(form,Path.Combine(evidence,"workspace-"+names[step]+"-"+theme+".png"));
    step++;if(step==1)form.Size=form.MinimumSize;else if(step==2){form.Size=new Size(1120,760);Field<RadioButton>(form,"settingsNav").PerformClick();form.SettingsEditor.SelectCategory(2);}else if(step==3)form.SettingsEditor.SelectCategory(1);else if(step==4){Field<RadioButton>(form,"homeNav").PerformClick();var a=new DeviceRecord{DisplayName="Demo workstation",DeviceId="123456789",UseDefaultRelay=true,SavePermanentPassword=true,PermanentPassword="synthetic-a"};var b=new DeviceRecord{DisplayName="Demo laptop",DeviceId="987654321",Host="192.168.1.25",Transport=DeviceTransport.Lan,Pin=RelayTls.DefaultPin,Port=8444,SavePermanentPassword=true,PermanentPassword="synthetic-b"};await (Task)Invoke(form,"Connect",a);await (Task)Invoke(form,"Connect",b);}else if(step==5){await (Task)Invoke(form,"Execute","echo authorized-demo");}else if(step==6)form.Size=form.MinimumSize;else{timer.Stop();form.Close();}
   }catch(Exception ex){error=ex;timer.Stop();form.Close();}finally{progressing=false;}};
   Application.Run(form);if(error!=null)throw error;
  }
  foreach(bool dark in new[]{false,true})foreach(bool warning in new[]{false,true})using(Form form=warning?(Form)new ActiveSessionCloseForm("Demo workstation"):new RemsupClientForm(false,new RemsupSupportPanel(()=>new RemsupSettings(),()=>new SupportStatus{DeviceId="111222333"})))using(var timer=new System.Windows.Forms.Timer{Interval=500}){Appearance.Dark=dark;Appearance.Apply(form);form.StartPosition=FormStartPosition.Manual;form.Location=new Point(8,8);form.TopMost=true;Exception error=null;form.Shown+=(s,e)=>timer.Start();timer.Tick+=(s,e)=>{try{FriendlyUiTests.Capture(form,Path.Combine(evidence,(warning?"active-close":"portable")+"-"+(dark?"dark":"light")+".png"));}catch(Exception ex){error=ex;}finally{timer.Stop();form.Close();}};Application.Run(form);if(error!=null)throw error;}
 }
 static System.Collections.Generic.IEnumerable<Control> Controls(Control root){foreach(Control c in root.Controls){yield return c;foreach(var descendant in Controls(c))yield return descendant;}}
 static object Invoke(object obj,string name,params object[] args){return obj.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(obj,args);}
 static T Field<T>(object owner,string name){return (T)owner.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(owner);}
 static T Find<T>(Control root)where T:Control{if(root is T)return (T)root;foreach(Control c in root.Controls){var child=Find<T>(c);if(child!=null)return child;}return null;}
 static void Pump(Task task){var watch=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&watch.ElapsedMilliseconds<5000){Application.DoEvents();Thread.Sleep(10);}Check(task.IsCompleted,"bounded checked connection");task.GetAwaiter().GetResult();}
 static void Check(bool value,string text){if(!value)throw new Exception("WorkspaceUiTests: "+text);}
}
